// connect reports whether the player's stones contain a chain from one side
// of the board to the opposite side.
//
// If alongRows is true the player must connect the top row to the bottom row
// (player O); otherwise the player must connect the left column to the right
// column (player X).
func connect(board []string, player byte, alongRows bool) bool {
	height := len(board)
	width := len(board[0])

	visited := make([][]bool, height)
	for i := range visited {
		visited[i] = make([]bool, width)
	}

	queue := make([][2]int, 0, height*width)
	for i := 0; i < height; i++ {
		for j := 0; j < width; j++ {
			onEdge := (alongRows && i == 0) || (!alongRows && j == 0)
			if onEdge && board[i][j] == player {
				visited[i][j] = true
				queue = append(queue, [2]int{i, j})
			}
		}
	}

	for len(queue) > 0 {
		cell := queue[0]
		queue = queue[1:]
		i, j := cell[0], cell[1]

		onGoal := (alongRows && i == height-1) || (!alongRows && j == width-1)
		if onGoal {
			return true
		}

		for _, d := range directions {
			ni, nj := i+d[0], j+d[1]
			if ni < 0 || ni >= height || nj < 0 || nj >= width {
				continue
			}
			if visited[ni][nj] || board[ni][nj] != player {
				continue
			}
			visited[ni][nj] = true
			queue = append(queue, [2]int{ni, nj})
		}
	}

	return false
}
