		return "", nil
	}

	width := len(lines[0])
	for _, l := range lines {
		if len(l) != width {
			return "", errors.New("connect: board rows must all have the same length")
		}
	}

	if connect(lines, 'X', false) {
		return "X", nil
	}
	if connect(lines, 'O', true) {
		return "O", nil
	}
	return "", nil
}
```

